	(428, 'woocommerce_marketplace_suggestions', 'a:2:{s:11:"suggestions";a:37:{i:0;a:1:{s:21:"recommendations-count";i:5;}i:1;a:4:{s:4:"slug";s:28:"product-edit-meta-tab-header";s:7:"context";a:1:{i:0;s:28:"product-edit-meta-tab-header";}s:5:"title";s:22:"Recommended extensions";s:13:"allow-dismiss";b:0;}i:2;a:7:{s:4:"slug";s:39:"product-edit-meta-tab-footer-browse-all";s:7:"context";a:1:{i:0;s:28:"product-edit-meta-tab-footer";}s:9:"link-text";s:21:"Discover more options";s:3:"url";s:64:"https://woocommerce.com/product-category/woocommerce-extensions/";s:7:"iam-url";s:55:"admin.php?page=wc-admin&tab=extensions&path=/extensions";s:8:"promoted";s:31:"category-woocommerce-extensions";s:13:"allow-dismiss";b:0;}i:3;a:4:{s:4:"slug";s:19:"orders-empty-header";s:7:"context";a:1:{i:0;s:24:"orders-list-empty-header";}s:5:"title";s:20:"Tools for your store";s:13:"allow-dismiss";b:0;}i:4;a:7:{s:4:"slug";s:30:"orders-empty-footer-browse-all";s:7:"context";a:1:{i:0;s:24:"orders-list-empty-footer";}s:9:"link-text";s:21:"Discover more options";s:3:"url";s:64:"https://woocommerce.com/product-category/woocommerce-extensions/";s:7:"iam-url";s:55:"admin.php?page=wc-admin&tab=extensions&path=/extensions";s:8:"promoted";s:31:"category-woocommerce-extensions";s:13:"allow-dismiss";b:0;}i:5;a:4:{s:4:"slug";s:35:"products-empty-header-product-types";s:7:"context";a:1:{i:0;s:26:"products-list-empty-header";}s:5:"title";s:23:"Other types of products";s:13:"allow-dismiss";b:0;}i:6;a:7:{s:4:"slug";s:32:"products-empty-footer-browse-all";s:7:"context";a:1:{i:0;s:26:"products-list-empty-footer";}s:9:"link-text";s:21:"Discover more options";s:3:"url";s:64:"https://woocommerce.com/product-category/woocommerce-extensions/";s:7:"iam-url";s:55:"admin.php?page=wc-admin&tab=extensions&path=/extensions";s:8:"promoted";s:31:"category-woocommerce-extensions";s:13:"allow-dismiss";b:0;}i:7;a:8:{s:4:"slug";s:50:"products-list-empty-body-woocommerce-subscriptions";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:25:"woocommerce-subscriptions";s:4:"icon";s:99:"https://woocommerce.com/wp-content/uploads/2012/09/Woo_Subscriptions_icon-marketplace-160x160-2.png";s:5:"title";s:25:"WooCommerce Subscriptions";s:4:"copy";s:514:"WooCommerce Subscriptions is a WooCommerce extension that lets customers subscribe to your products or services and pay on a weekly, monthly, or annual basis. It integrates with over 25 payment gateways for automatic recurring payments and supports automatic rebilling on failed subscription payments. Subscribers can manage their own plan — upgrading, downgrading, suspending, or canceling — and update their shipping address or payment method. It\'s a paid annual extension with a 30-day money-back guarantee.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:59:"https://woocommerce.com/products/woocommerce-subscriptions/";}i:8;a:8:{s:4:"slug";s:45:"products-list-empty-body-woocommerce-bookings";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:20:"woocommerce-bookings";s:4:"icon";s:90:"https://woocommerce.com/wp-content/uploads/2014/05/Bookings_icon-marketplace-160x160-1.png";s:5:"title";s:20:"WooCommerce Bookings";s:4:"copy";s:497:"WooCommerce Bookings is the official WooCommerce extension that lets store owners sell appointments, reservations, rentals, or classes with bookable time or date slots. It supports fixed time slots or flexible ranges, group and individual pricing, and resources — staff, rooms, or equipment — each with its own availability to prevent double-booking. It syncs with Google Calendar and works with any WooCommerce payment gateway. It\'s a paid annual extension with a 30-day money-back guarantee.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:54:"https://woocommerce.com/products/woocommerce-bookings/";}i:9;a:8:{s:4:"slug";s:48:"products-list-empty-body-woocommerce-memberships";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:23:"woocommerce-memberships";s:4:"icon";s:78:"https://woocommerce.com/wp-content/uploads/2015/06/skyverge-wc-icon-b2vhw6.png";s:5:"title";s:23:"WooCommerce Memberships";s:4:"copy";s:139:"Power your membership association, online magazine, elearning sites, and more with access control to content/products and member discounts.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:57:"https://woocommerce.com/products/woocommerce-memberships/";}i:10;a:8:{s:4:"slug";s:40:"products-list-empty-body-product-bundles";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:27:"woocommerce-product-bundles";s:4:"icon";s:97:"https://woocommerce.com/wp-content/uploads/2012/07/Product_Bundles_icon-marketplace-160x160-2.png";s:5:"title";s:15:"Product Bundles";s:4:"copy";s:84:"Offer personalized product bundles, bulk discount packages, and assembled products.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:49:"https://woocommerce.com/products/product-bundles/";}i:11;a:8:{s:4:"slug";s:40:"products-list-empty-body-product-add-ons";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:26:"woocommerce-product-addons";s:4:"icon";s:96:"https://woocommerce.com/wp-content/uploads/2013/05/Product_Addons_icon-marketplace-160x160-2.png";s:5:"title";s:15:"Product Add-Ons";s:4:"copy";s:94:"Offer add-ons like gift wrapping, special messages or other special options for your products.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:49:"https://woocommerce.com/products/product-add-ons/";}i:12;a:8:{s:4:"slug";s:40:"products-list-empty-body-dynamic-pricing";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:27:"woocommerce-dynamic-pricing";s:4:"icon";s:94:"https://woocommerce.com/wp-content/uploads/2012/02/woocommerce-dynamic-pricing-icon-upload.png";s:5:"title";s:15:"Dynamic Pricing";s:4:"copy";s:135:"Quantity discounts, tiered pricing, BOGO offers, wholesale and role-based pricing, and category and cart-total discounts in one engine.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:49:"https://woocommerce.com/products/dynamic-pricing/";}i:13;a:8:{s:4:"slug";s:43:"products-list-empty-body-composite-products";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:30:"woocommerce-composite-products";s:4:"icon";s:100:"https://woocommerce.com/wp-content/uploads/2013/06/Composite_Products_icon-marketplace-160x160-1.png";s:5:"title";s:18:"Composite Products";s:4:"copy";s:85:"Create product kit builders and custom product configurators using existing products.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:52:"https://woocommerce.com/products/composite-products/";}i:14;a:8:{s:4:"slug";s:56:"products-list-empty-body-bulk-order-form-for-woocommerce";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:31:"bulk-order-form-for-woocommerce";s:4:"icon";s:88:"https://woocommerce.com/wp-content/uploads/2020/04/Bulk-Order-Form-For-WooCommerce-3.png";s:5:"title";s:32:"Bulk Order – B2B Product Table";s:4:"copy";s:115:"Revolutionize product tables through Bulk Order Form for WooCommerce. Add sorting, search, pagination, and filters.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:65:"https://woocommerce.com/products/bulk-order-form-for-woocommerce/";}i:15;a:8:{s:4:"slug";s:55:"products-list-empty-body-woocommerce-points-and-rewards";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:30:"woocommerce-points-and-rewards";s:4:"icon";s:100:"https://woocommerce.com/wp-content/uploads/2013/06/Points_and_Rewards_icon-marketplace-160x160-2.png";s:5:"title";s:30:"WooCommerce Points and Rewards";s:4:"copy";s:102:"Reward your customers for purchases and other actions with points which can be redeemed for discounts.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:64:"https://woocommerce.com/products/woocommerce-points-and-rewards/";}i:16;a:8:{s:4:"slug";s:35:"products-list-empty-body-gift-cards";s:7:"context";s:24:"products-list-empty-body";s:7:"product";s:22:"woocommerce-gift-cards";s:4:"icon";s:92:"https://woocommerce.com/wp-content/uploads/2020/03/Gift_Cards_icon-marketplace-160x160-1.png";s:5:"title";s:10:"Gift Cards";s:4:"copy";s:495:"Gift Cards for WooCommerce is the official WooCommerce extension for selling prepaid, multi-purpose digital gift cards that customers redeem online. It supports Simple and Variable gift certificates, expiring codes, custom delivery dates, and multiple recipients, and lets store owners track, search, and report on issued, used, and expired codes. Unlike a coupon, it treats gift cards as prepaid balances for accurate accounting. It\'s a paid annual extension with a 30-day money-back guarantee.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:44:"https://woocommerce.com/products/gift-cards/";}i:17;a:9:{s:4:"slug";s:42:"orders-list-empty-body-table-rate-shipping";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:31:"woocommerce-table-rate-shipping";s:4:"icon";s:101:"https://woocommerce.com/wp-content/uploads/2012/07/Table_Rate_Shipping_icon-marketplace-160x160-2.png";s:5:"title";s:19:"Table Rate Shipping";s:4:"copy";s:123:"Advanced, flexible shipping. Define multiple shipping rates based on location, price, weight, shipping class or item count.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:53:"https://woocommerce.com/products/table-rate-shipping/";s:9:"is_pinned";b:1;}i:18;a:9:{s:4:"slug";s:40:"orders-list-empty-body-shipment-tracking";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:29:"woocommerce-shipment-tracking";s:4:"icon";s:99:"https://woocommerce.com/wp-content/uploads/2012/05/Shipment_Tracking_icon-marketplace-160x160-2.png";s:5:"title";s:17:"Shipment Tracking";s:4:"copy";s:49:"Add shipment tracking information to your orders.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:51:"https://woocommerce.com/products/shipment-tracking/";s:9:"is_pinned";b:1;}i:19;a:9:{s:4:"slug";s:56:"orders-list-empty-body-conditional-shipping-and-payments";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:45:"woocommerce-conditional-shipping-and-payments";s:4:"icon";s:111:"https://woocommerce.com/wp-content/uploads/2015/03/Conditional_Shipping_Payments_icon-marketplace-160x160-1.png";s:5:"title";s:33:"Conditional Shipping and Payments";s:4:"copy";s:91:"Use conditional logic to restrict the shipping and payment options available on your store.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:67:"https://woocommerce.com/products/conditional-shipping-and-payments/";s:9:"is_pinned";b:1;}i:20;a:9:{s:4:"slug";s:46:"orders-list-empty-body-shipstation-integration";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:35:"woocommerce-shipstation-integration";s:4:"icon";s:73:"https://woocommerce.com/wp-content/uploads/2012/08/ShipStation-Icon-1.png";s:5:"title";s:11:"ShipStation";s:4:"copy";s:113:"Ship your WooCommerce orders with confidence, save on top carriers, and automate your processes with ShipStation.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:57:"https://woocommerce.com/products/shipstation-integration/";s:9:"is_pinned";b:1;}i:21;a:9:{s:4:"slug";s:41:"orders-list-empty-body-woocommerce-zapier";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:18:"woocommerce-zapier";s:4:"icon";s:76:"https://woocommerce.com/wp-content/uploads/2013/09/Zapier-App-Icon-160-1.png";s:5:"title";s:18:"Zapier Integration";s:4:"copy";s:153:"WooCommerce connected to 9,000+ apps, with AI steps inside your workflows and plain-English store management through Claude or ChatGPT. No code required.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:52:"https://woocommerce.com/products/woocommerce-zapier/";s:9:"is_pinned";b:1;}i:22;a:9:{s:4:"slug";s:34:"orders-list-empty-body-automatewoo";s:7:"context";s:22:"orders-list-empty-body";s:7:"product";s:11:"automatewoo";s:4:"icon";s:70:"https://woocommerce.com/wp-content/uploads/2019/10/woo-AutomateWoo.png";s:5:"title";s:11:"AutomateWoo";s:4:"copy";s:121:"Powerful marketing automation for WooCommerce. AutomateWoo has the tools you need to grow your store and make more money.";s:11:"button-text";s:10:"Learn More";s:3:"url";s:45:"https://wooc